use crate::bridge::extern_c_api as extern_api;
use data::*;

use proptest::prelude::*;

/// container for component's incoming port values
pub struct PreStateContainer {
  pub api_aircraftAttitude: FlightStack::AircraftAttitude
}

/// setter for component's incoming port values
pub fn put_concrete_inputs_container(container: PreStateContainer)
{
  put_aircraftAttitude(container.api_aircraftAttitude);
}

/// setter for component's incoming port values
pub fn put_concrete_inputs(aircraftAttitude: FlightStack::AircraftAttitude)
{
  put_aircraftAttitude(aircraftAttitude);
}

/// setter for IN DataPort
pub fn put_aircraftAttitude(value: FlightStack::AircraftAttitude)
{
  *extern_api::IN_aircraftAttitude.lock().unwrap_or_else(|e| e.into_inner()) = Some(value)
}

/// getter for OUT DataPort
pub fn get_qualifiedAttitude() -> FlightStack::QualifiedAttitude
{
  return extern_api::OUT_qualifiedAttitude.lock().unwrap_or_else(|e| e.into_inner()).expect("Not expecting None")
}
